  return items[0];
}

const firstId = first(["a", "b"]);

type Status = "OPEN" | "DONE";

function label(status: Status) {
  switch (status) {
    case "OPEN": return "Open";
    case "DONE": return "Done";
    default: { const impossible: never = status; return impossible; }
  }
}

