type TaskId = string;
type TaskStatus = "OPEN" | "DONE";
type TaskDto = { id: TaskId; title: string; status: TaskStatus };

async function getTask(id: TaskId): Promise<TaskDto> {
  const r = await fetch(`/api/tasks/${id}`);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.json();
}
